run.command:
$ErrorActionPreference = 'SilentlyContinue'
$secs = 10; $keep = $false
$pr = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
if (-not $pr.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) { 'CAPTURE-ERROR: packet capture needs administrator rights. Use "Run as admin" at the top of the window, then run this again.'; exit 1 }
$work = Join-Path $env:TEMP 'netdeck-capture'; New-Item -ItemType Directory -Force -Path $work | Out-Null
$etl = Join-Path $work 'capture.etl'; $txt = Join-Path $work 'capture.txt'; $pcap = ''
pktmon stop 2>&1 | Out-Null; pktmon filter remove 2>&1 | Out-Null
Remove-Item -LiteralPath $etl, $txt -Force
$started = pktmon start --capture --comp nics --pkt-size 256 --file-name $etl --file-size 200 2>&1
if ($LASTEXITCODE -ne 0) { 'CAPTURE-ERROR: pktmon could not start. ' + (($started | Out-String).Trim()); exit 1 }
'Capturing on all adapters for ' + $secs + ' s (pktmon, NIC level, first 256 bytes of each packet). Use the network normally...'
Start-Sleep -Seconds $secs
pktmon stop 2>&1 | Out-Null
pktmon etl2txt $etl --out $txt 2>&1 | Out-Null
if ($keep) { $pcap = Join-Path ([Environment]::GetFolderPath('Desktop')) ('netdeck-capture-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.pcapng'); pktmon etl2pcap $etl --out $pcap 2>&1 | Out-Null }
$local = @{}; Get-NetIPAddress | ForEach-Object { $local[$_.IPAddress.Split('%')[0]] = $true }
$adapters = @(Get-NetAdapter -Physical | Where-Object { $_.Status -eq 'Up' } | ForEach-Object { $_.Name }) -join ', '
$svc = @{ 53 = 'DNS'; 80 = 'HTTP'; 443 = 'HTTPS'; 22 = 'SSH'; 25 = 'SMTP'; 587 = 'SMTP'; 993 = 'IMAPS'; 123 = 'NTP'; 67 = 'DHCP'; 68 = 'DHCP'; 137 = 'NetBIOS'; 138 = 'NetBIOS'; 139 = 'NetBIOS'; 445 = 'SMB'; 3389 = 'RDP'; 5353 = 'mDNS'; 1900 = 'SSDP'; 5355 = 'LLMNR'; 3702 = 'WS-Discovery'; 1194 = 'OpenVPN'; 51820 = 'WireGuard'; 500 = 'IKE (VPN)'; 4500 = 'IKE (VPN)'; 8080 = 'HTTP-alt'; 5432 = 'PostgreSQL'; 3306 = 'MySQL'; 6379 = 'Redis'; 1433 = 'SQL Server'; 3478 = 'STUN (calls)'; 5060 = 'SIP'; 8443 = 'HTTPS-alt'; 546 = 'DHCPv6'; 547 = 'DHCPv6' }
$proto = @{}; $hosts = @{}; $dns = @{}; $raw = New-Object Collections.Generic.List[string]
$pk = 0; $bytesIn = 0; $bytesOut = 0; $unparsed = 0; $lines = 0; $capLines = 400000
function Split-Endpoint($s) { if ($s -match '^(\d+\.\d+\.\d+\.\d+)\.(\d+)$') { return @($Matches[1], [int]$Matches[2]) }; if ($s -match '^([0-9A-Fa-f:]+)\.(\d+)$') { return @($Matches[1], [int]$Matches[2]) }; return @($s, 0) }
function Is-Group($ip) { return ($ip -match '^(224\.|239\.|255\.255\.255\.255|ff0)') -or ($ip -like '*.255') }
function Is-Lan($ip) { return $ip -match '^(10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|169\.254\.|fe80:|fd|fc)' }
function Add-Packet($t, $dir, $size) {
  $script:pk++; if ($dir -eq 'Rx') { $script:bytesIn += $size } else { $script:bytesOut += $size }
  if ($raw.Count -lt 15) { $raw.Add($t) }
  if ($t -match 'ethertype ARP') { $proto['ARP'] = [int]$proto['ARP'] + 1; return }
  $body = $t; if ($t -match 'length \d+: (.*)$') { $body = $Matches[1] }
  if ($body -notmatch '^(\S+) > (\S+?):? (.*)$') { $script:unparsed++; return }
  $sp = Split-Endpoint $Matches[1]; $dp = Split-Endpoint $Matches[2]; $rest = $Matches[3]
  $l4 = 'other'
  if ($rest -like 'Flags *') { $l4 = 'TCP' } elseif ($rest -match '^UDP|UDP, length|^\d+[+*]? |\d+/\d+/\d+') { $l4 = 'UDP' } elseif ($rest -match 'ICMP6|ICMPv6') { $l4 = 'ICMPv6' } elseif ($rest -match 'ICMP') { $l4 = 'ICMP' }
  $port = 0; if ($svc.ContainsKey($dp[1])) { $port = $dp[1] } elseif ($svc.ContainsKey($sp[1])) { $port = $sp[1] } elseif ($dp[1] -and $sp[1]) { $port = [math]::Min($dp[1], $sp[1]) }
  $label = $l4
  if ($l4 -eq 'TCP' -or $l4 -eq 'UDP') { $name = $svc[$port]; if ($l4 -eq 'UDP' -and $port -eq 443) { $name = 'QUIC' }; if ($name) { $label = $name + ' (' + $l4 + ' ' + $port + ')' } else { $label = $l4 + ' other' } }
  $proto[$label] = [int]$proto[$label] + 1
  if ($rest -match '\b(A|AAAA|HTTPS|PTR|SRV|TXT|MX|CNAME)\? ([A-Za-z0-9._-]+)\.') { $n = $Matches[2].ToLower(); if ($n -notmatch '\.arpa$') { $dns[$n] = [int]$dns[$n] + 1 } }
  $other = $null; if ($local[$sp[0]]) { $other = $dp[0] } elseif ($local[$dp[0]]) { $other = $sp[0] }
  if (-not $other -or (Is-Group $other)) { return }
  if (-not $hosts.ContainsKey($other)) { $hosts[$other] = @{ Packets = 0; Bytes = 0; Protos = @{} } }
  $h = $hosts[$other]; $h.Packets++; $h.Bytes += $size; $h.Protos[$label] = [int]$h.Protos[$label] + 1
}
$rd = New-Object IO.StreamReader($txt); $dir = ''; $size = 0
while (($line = $rd.ReadLine()) -ne $null) {
  $lines++; if ($lines -gt $capLines) { break }
  if ($line -match 'Direction (Rx|Tx).*OriginalSize (\d+)') {
    $dir = $Matches[1]; $size = [int]$Matches[2]
    if ($line -match 'LoggedSize \d+[,\s]+(\S.* > .*)$') { Add-Packet $Matches[1].Trim() $dir $size; $dir = '' }
    continue
  }
  if (-not $dir) { continue }
  Add-Packet $line.Trim() $dir $size; $dir = ''
}
$rd.Close()
function Fmt-Bytes($b) { if ($b -ge 1MB) { return ('{0:n1} MB' -f ($b / 1MB)) }; if ($b -ge 1KB) { return ('{0:n0} KB' -f ($b / 1KB)) }; return ($b.ToString() + ' B') }
$total = $bytesIn + $bytesOut
if ($pk -eq 0) { 'CAPTURE-ERROR: no packets were captured in ' + $secs + ' s. pktmon may not see this adapter, or nothing was sent.'; exit 1 }
'Captured ' + $secs + ' s on ' + $adapters + ': ' + $pk.ToString('n0') + ' packets, ' + (Fmt-Bytes $total) + ' (received ' + (Fmt-Bytes $bytesIn) + ', sent ' + (Fmt-Bytes $bytesOut) + ')'
if ($lines -gt $capLines) { 'Note: only the first ' + $capLines.ToString('n0') + ' lines of the capture were summarised.' }
if ($pcap) { 'Saved for Wireshark: ' + $pcap }
''
'By protocol'
($proto.GetEnumerator() | Sort-Object { $_.Value } -Descending | Select-Object -First 15 | ForEach-Object { [pscustomobject]@{ Protocol = $_.Key; Packets = $_.Value; Share = ('{0:p0}' -f ($_.Value / $pk)) } } | Format-Table -AutoSize | Out-String -Width 4096).TrimEnd(); ''
$remote = @($hosts.GetEnumerator() | Where-Object { -not (Is-Lan $_.Key) } | Sort-Object { $_.Value.Bytes } -Descending | Select-Object -First 12)
$peers = @($hosts.GetEnumerator() | Where-Object { Is-Lan $_.Key } | Sort-Object { $_.Value.Bytes } -Descending | Select-Object -First 12)
$look = @(foreach ($r in $remote) { [pscustomobject]@{ IP = $r.Key; Task = [System.Net.Dns]::GetHostEntryAsync($r.Key) } })
if ($look.Count) { try { [void][System.Threading.Tasks.Task]::WaitAll([System.Threading.Tasks.Task[]]@($look | ForEach-Object { $_.Task }), 3000) } catch { } }
$names = @{}; foreach ($l in $look) { if ($l.Task.Status -eq 'RanToCompletion') { $n = $l.Task.Result.HostName; if ($n -and $n -ne $l.IP) { $names[$l.IP] = $n } } }
function Host-Rows($set) { foreach ($r in $set) { [pscustomobject]@{ Address = $r.Key; Name = [string]$names[$r.Key]; Packets = $r.Value.Packets; Data = (Fmt-Bytes $r.Value.Bytes); Traffic = (($r.Value.Protos.GetEnumerator() | Sort-Object { $_.Value } -Descending | Select-Object -First 3 | ForEach-Object { $_.Key }) -join ', ') } } }
'Top internet hosts (' + $remote.Count + ' shown)'
if ($remote.Count) { (Host-Rows $remote | Format-Table -AutoSize | Out-String -Width 4096).TrimEnd() } else { '  none' }; ''
'Local network peers (' + $peers.Count + ' shown)'
if ($peers.Count) { (Host-Rows $peers | Format-Table -AutoSize | Out-String -Width 4096).TrimEnd() } else { '  none' }; ''
'DNS lookups (' + $dns.Count + ' names)'
if ($dns.Count) { ($dns.GetEnumerator() | Sort-Object { $_.Value } -Descending | Select-Object -First 25 | ForEach-Object { [pscustomobject]@{ Name = $_.Key; Queries = $_.Value } } | Format-Table -AutoSize | Out-String -Width 4096).TrimEnd() } else { '  none' }; ''
if ($unparsed) { 'Packets NetDeck could not classify: ' + $unparsed; '' }
'First packets (as decoded by pktmon)'
$raw | ForEach-Object { '  ' + $_ }
Remove-Item -LiteralPath $etl, $txt -Force

