    $snap[[string]$c.Id] = @{ Name = [string]$c.Name; Type = $type; M = $bag.M; Reason = $bag.Reason }
  }
  return $snap
}
function Sum-Keys($m, $pattern, $exclude) { $s = 0.0; foreach ($k in $m.Keys) { if ($k -match $pattern -and ($exclude -eq '' -or $k -notmatch $exclude)) { $s += $m[$k] } }; return $s }
