''
$dropsTotal = 0; foreach ($r in $rows) { $dropsTotal += $r.Drops }
if ($dropsTotal -eq 0) { 'No packets were dropped anywhere in the stack during the run.' } else { 'Dropped in total: ' + $dropsTotal + '. The Type and reason columns say which layer dropped them (a firewall or VPN filter driver is the usual culprit; the adapter itself points to a cable/Wi-Fi problem).' }
''
'Counter fields pktmon reported: ' + ((@($first.Values | ForEach-Object { $_.M.Keys }) | Sort-Object -Unique) -join ', ')

